WITH chosen AS (SELECT * FROM operation_schedules WHERE run_id=${run_id:sqlstring} AND step=${step:raw}), times AS (SELECT start AS t FROM chosen UNION SELECT "end" AS t FROM chosen) SELECT TIMESTAMPTZ '1970-01-01 00:00:00+00' + t * INTERVAL '1 second' AS time,(SELECT 'J'||(job+1)||'/O'||(operation+1) FROM chosen s WHERE machine=0 AND s.start<=t AND s."end">t LIMIT 1) AS "Machine 1",(SELECT 'J'||(job+1)||'/O'||(operation+1) FROM chosen s WHERE machine=1 AND s.start<=t AND s."end">t LIMIT 1) AS "Machine 2",(SELECT 'J'||(job+1)||'/O'||(operation+1) FROM chosen s WHERE machine=2 AND s.start<=t AND s."end">t LIMIT 1) AS "Machine 3",(SELECT 'J'||(job+1)||'/O'||(operation+1) FROM chosen s WHERE machine=3 AND s.start<=t AND s."end">t LIMIT 1) AS "Machine 4",(SELECT 'J'||(job+1)||'/O'||(operation+1) FROM chosen s WHERE machine=4 AND s.start<=t AND s."end">t LIMIT 1) AS "Machine 5",(SELECT 'J'||(job+1)||'/O'||(operation+1) FROM chosen s WHERE machine=5 AND s.start<=t AND s."end">t LIMIT 1) AS "Machine 6" FROM times ORDER BY t;
